-- Las unidades disponibles/reservadas del seed de iStore van a "Depósito 1"
-- (decisión de Dario, 16-09-2026). Tránsito y vendidas quedan sin ubicación.

DO $$
DECLARE
  v_tenant_id TEXT;
  v_location_id TEXT;
BEGIN
  SELECT id INTO v_tenant_id FROM "Tenant" WHERE lower(email) = 'dariodeoli@gmail.com' OR lower(name) LIKE '%istore%' OR lower(name) LIKE '%iphone store%' ORDER BY "createdAt" LIMIT 1;
  IF v_tenant_id IS NULL THEN RETURN; END IF;
  SELECT l."id" INTO v_location_id FROM "StockLocation" l JOIN "Branch" b ON b."id" = l."branchId" WHERE l."tenantId" = v_tenant_id AND l."name" = 'Depósito 1' AND b."isActive" = true ORDER BY l."createdAt" LIMIT 1;
  IF v_location_id IS NULL THEN RETURN; END IF;
  UPDATE "InventoryUnit" SET "locationId" = v_location_id, "updatedAt" = now() WHERE "tenantId" = v_tenant_id AND "status" IN ('AVAILABLE', 'RESERVED') AND "locationId" IS NULL AND "serial" IN ('358110348557633', '354349817961769', '352941880936702', '351509526775973', '356942287694601', '356144894699848', '353742330249699', '359339131244831', '353742333936714', '352013406872280', '354807374920031', '350928999006743', '350352933841042', '359003856143772', '359695609855873', '359843528986441', '351592242608710', '350352935040577', '353557672330166', '351929294968107', '352013400583735', '351592245504569', '359014538753532', '353555374164321', '352013403252494', '356165444210380', '353092220272983', '353294706402692', '352130219685111', '352228707422342', '358790736845300', '353664575205832', '358790730114927', '351284085061039', '353429716092063', '351284085159064', '354672345495772', '354183138520982', '351284081588720', '350308310561785', '353177646551134', '353887197145090', '353992311652201', '357004280081887', '351048874532074', '358668285318459', '350448885157963', '357292745619751', '351698478944610', '356562916063398', '354553492365986', '354029283479682', '357981365970003', '350390278392189', '356321254423437', '352156543747509', '356562917352030', '350390273537416', '358348182229147', '354300582290835', '355473497966945', '358348184749449', '353629306854133', '352772254904392', '352400475500811', '353431655062990', '354300588034468', '354070965254662', '354058241357292', '354379779193242', '359711539895937', '351646278518027', '358606715748689', '352310725205394', '351306993563770', '355430971369111', '351503405497999', '354379770021434', '354379773935028', '352958413789754', '356140776460879', '359696880887718', '359954318105041', '352404325247185', '351288156287662', '350304978232868', '354566766196051', '351811693839073', '351418496874743', '351811698316986', '352703944072886', '359072841628510', '357017256428403', '358282728900798', '354359260956315', '